{"function":"() => {
const parse = c => { const m = c.match(/[\d.]+/g).map(Number); return {r:m[0],g:m[1],b:m[2],a:m.length>3?m[3]:1}; };
const lum = ({r,g,b}) => { const f = v => { v/=255; return v<=0.03928? v/12.92 : Math.pow((v+0.055)/1.055,2.4); }; return 0.2126*f(r)+0.7152*f(g)+0.0722*f(b); };
const bg = e => { while (e) { const c = parse(getComputedStyle(e).backgroundColor); if (c.a>0) return c; e = e.parentElement || (e.getRootNode().host); } return {r:255,g:255,b:255,a:1}; };
const ratio = (a,b) => { const l1=lum(a), l2=lum(b); return ((Math.max(l1,l2)+0.05)/(Math.min(l1,l2)+0.05)).toFixed(2); };
const chk = (label, e) => { if(!e) return label+': none'; const cs = getComputedStyle(e); const fg = parse(cs.color); const b = bg(e); return label+': '+cs.color+' on '+JSON.stringify(b)+' = '+ratio(fg,b)+' fs='+cs.fontSize+' fw='+cs.fontWeight; };
const out = [];
out.push(chk('chip text', document.querySelector('.br-tag.interaction span.text-gray-50')));
out.push(chk('meus processos', document.querySelector('.br-tag.interaction .text-truncate')));
document.querySelectorAll('pnip-status-solicitacao-utils .text-center').forEach(e=>out.push(chk('status '+e.textContent.trim(), e)));
out.push(chk('ultima', document.querySelector('.mb-2')));
out.push(chk('th', document.querySelector('th[scope=col]')));
out.push(chk('td', document.querySelector('tbody td')));
out.push(chk('num link', document.querySelector('td a[role=button]')));
const bc = document.querySelector('br-breadcrumb').shadowRoot.querySelector('li[data-active] span'); out.push(chk('bc', bc));
const inp = document.querySelector('br-input').shadowRoot.querySelector('input'); const ph = getComputedStyle(inp, '::placeholder'); out.push('placeholder: '+ph.color+' bg '+getComputedStyle(inp).backgroundColor+' fs '+ph.fontSize);
const tabs = document.querySelector('br-tab').shadowRoot.querySelectorAll('button'); tabs.forEach(t=>out.push(chk('tab '+t.textContent.trim(), t.querySelector('.name'))));
out.push(chk('assinar', document.querySelector('br-button[title=Assinar]').shadowRoot.querySelector('button')));
const icons = [...document.querySelectorAll('br-icon-base')].slice(0,3).map(i=>chk('icon '+i.getAttribute('icon-name'), i.shadowRoot ? (i.shadowRoot.querySelector('i,svg')||i) : i));
out.push(...icons);
out.push(chk('perfil', document.querySelector('.dropdown-user-perfil')));
out.push(chk('ola', document.querySelector('.br-sign-in .text-gray-80')));
return out; }"}

